/**
 * @method
 * @name dts_fileList_OnLoadCompleted
 * @description dts_fileList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_fileList_OnLoadCompleted = function(rowcount) {
    try {
        let setArr = [txb_file_name1, txb_file_name2, txb_file_name3, txb_file_name4, txb_file_name5];
        if (rowcount > 0) {
            let k;
            for (let i = 0; i < rowcount; i++) {
                k = dts_fileList.getCellData(i + 1, "SEQ");
                setArr[k - 1].setValue(dts_fileList.getCellData(i + 1, "filename"));
                // if(dts_fileList.NameString(i+1, "filename") ==""){setBtn[i].disabled=true;}

            }
        }
        dts_fileList.setBroadcast(false);
        for (let i = rowcount; i < 5; i++) {
            dts_fileList.insertRow();
            dts_fileList.setCellData(i + 1, "SEQ", i + 1);
        }
        dts_fileList.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60010.dts_fileList_OnLoadCompleted" });
    }
};

