/**
 * @method
 * @name img_row_delete_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_row_delete_onclick = function() {
    try {
        let count = dts_Cmt.getRowCount();
        dts_Cmt.setBroadcast(false);
        for (let j = count; j > 0; j--) {
            if (dts_Cmt.getCellData(j, "CHECK") === 'T') {
                dts_Cmt.removeRow(j);
                scwin.fn_deleteRow();
            }
        }
        dts_Cmt.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60010.img_row_delete_onclick" });
    }
};

/**
 * @method
 * @name grd_cmt_onheadcheckclick
 * @description grd_cmt onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_cmt_onheadcheckclick = function(col, colid, bCheck) {
    try {
        let count = dts_Cmt.getRowCount();
        if (bCheck === '1') {
            dts_Cmt.setBroadcast(false);
            for (let j = 1; j <= count + 1; j++) {
                dts_Cmt.setCellData(j, "CHECK", 'T');
            }
            dts_Cmt.setBroadcast(true, true);
        } else {
            dts_Cmt.setBroadcast(false);
            for (let j = 1; j <= count + 1; j++) {
                dts_Cmt.setCellData(j, "CHECK", '');
            }
            dts_Cmt.setBroadcast(true, true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60010.grd_cmt_onheadcheckclick" });
    }
};

