///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description search function end
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(jobType) {
    // 2009.05.12 위원회일/철회일 필수 체크
    if (med_ListComiteDd.getValue() === "") {
        await $c.win.alert("위원회일을 입력하여 주세요");
        med_ListComiteDd.focus();
        return false;
    }
    const check = scwin.fileYnCheck();
    let vScrenProcTpCd;
    if (jobType === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    const cnt = dts_Cmt.getRowCount();
    for (let i = 1; i < cnt + 1; i++) {
        const comiteCaseNm = dts_Cmt.getCellData(i, "COMITE_CASE_NM");
        const comiteCaseNo = dts_Cmt.getCellData(i, "COMITE_CASE_NO");
        const comiteCaseTpCd = dts_Cmt.getCellData(i, "COMITE_CASE_TP_CD");
        if (scwin.vListComiteDd !== med_ListComiteDd.getValue()) {
            dts_Cmt.setCellData(i, "LIST_COMITE_DD", med_ListComiteDd.getValue());
        }
        if (comiteCaseNo === '') {
            await $c.win.alert('[안건번호]가 입력되지 않았습니다.');
            return false;
        }
        if (comiteCaseTpCd === '') {
            await $c.win.alert('[안건구분]이 입력되지 않았습니다.');
            return false;
        }
        if (comiteCaseNm === '') {
            await $c.win.alert('[안건명]이 입력되지 않았습니다.');
            return false;
        }
    }
    if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
        if (scwin.strKeyListComiteDelibCaseSeq === "") {
            scwin.listComiteDelibCaseSeq = await scwin.getListComiteDelibCaseSeq();
            dts_ReqInf.insertRow();
            dts_ReqInf.setCellData(1, "LIST_COMITE_DELIB_CASE_SEQ", scwin.listComiteDelibCaseSeq);
            scwin.strKeyListComiteDelibCaseSeq = scwin.listComiteDelibCaseSeq;
        }
        tr_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_tr_Save",
            action : "/ComiteDelib.do",
            ref : "dts_ReqInf,dts_Cmt,dts_fileList",
            target : "tr_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else if (!$c.cp.isModified(dts_ReqInf) && !$c.cp.isModified(dts_Cmt) && check === "Y") {
        const sbmOptions = {
            id : "sbm_tr_File",
            action : "/ComiteDelib.do",
            ref : "dts_fileList",
            target : "tr_File=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else {
        await $c.win.alert(scwin.MGS_NO_UPDT);
    }
};

