/**
 * @method
 * @name addNewCmt
 * @description add New Cmt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addNewCmt = async function() {
    const listComiteDd = med_ListComiteDd.getValue();
    const listComiteRnd = tbx_LIST_COMITE_RND.getValue();
    const listComiteRndExecYY = tbx_LIST_COMITE_RND_EXEC_YY.getValue();
    if (listComiteDd === '') {
        await $c.win.alert('위원회일을 입력해 주십시오');
        return;
    }
    if (listComiteRnd === "") {
        await $c.win.alert('회차를 입력해 주십시오');
        return;
    }
    if (dts_Cmt.getRowCount() > 0) {
        scwin.lastPosition = dts_Cmt.getCellData(dts_Cmt.getRowCount(), "COMITE_CASE_NO");
    }
    dts_Cmt.insertRow();
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "LIST_COMITE_DELIB_CASE_SEQ", scwin.strKeyListComiteDelibCaseSeq);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "LIST_COMITE_DD", listComiteDd);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "LIST_COMITE_RND_EXEC_YY", listComiteRndExecYY);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "LIST_COMITE_RND", listComiteRnd);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_NO", parseInt(scwin.lastPosition++));
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_NO_NM", "제" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_NO") + "호");
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_DTL_NO", '1');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD", '1');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_MAJAGNT_DEP_TP_CD", rdo_COMITE_CASE_MAJAGNT_DEP_TP_CD.getValue());
    lastPostion = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_NO");
};

