/**
 * @method
 * @name fn_deleteRow
 * @description delete Row 처리
 * @returns {void}
 * @hidden N
 */
scwin.fn_deleteRow = function() {
    let count = dts_Cmt.getRowCount();
    dts_Cmt.setBroadcast(false);
    for (let j = 1; j <= count + 1; j++) {
        if (dts_Cmt.getCellData(j, "CHECK") === 'T') {
            dts_Cmt.removeRow(j);
        }
    }
    dts_Cmt.setBroadcast(true, true);
};

/**
 * @method
 * @name addRow
 * @description add Row 처리
 * @param {*} attach_seq attach_seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addRow = async function(attach_seq) {
    if (dts_ReqInf.getRowCount() === 0) {
        await $c.win.alert('안건을 등록해 주십시오');
        return;
    }
    let setArr = [txb_file_name1, txb_file_name2, txb_file_name3, txb_file_name4, txb_file_name5];
    dts_fileList.setRowPosition(attach_seq, 0);
    inf_find.open();
    if (inf_find.getValue() !== "") {
        setArr[attach_seq - 1].setValue(inf_find.getValue());
    }
};

/**
 * @method
 * @name fn_DeleteRow
 * @description Delete Row 처리
 * @param {*} attach_seq attach_seq
 * @returns {void}
 * @hidden N
 */
scwin.fn_DeleteRow = function(attach_seq) {
    let setArr = [txb_file_name1, txb_file_name2, txb_file_name3, txb_file_name4, txb_file_name5];
    setArr[attach_seq - 1].setValue("");
    dts_fileList.setRowPosition(attach_seq, 0);
    if (dts_fileList.getCellData(attach_seq, "filename") !== "") {
        scwin.file_flag = "Y";
    }
    dts_fileList.setCellData(attach_seq, "fileinfo", "");
    dts_fileList.setCellData(attach_seq, "fileUrl", "");
    dts_fileList.removeRow(attach_seq);
    dts_fileList.insertRow(attach_seq - 1);
    dts_fileList.setCellData(attach_seq, "SEQ", attach_seq);
};

